use vstd::prelude::*;

verus! {

/// Elementwise “strictly greater”: for all i, a[i] > b[i].
spec fn vec_strictly_greater(a: Seq<int>, b: Seq<int>) -> bool {
    a.len() == b.len()
        && (forall|i: int| 0 <= i < a.len() ==> a[i] > b[i])
}

fn is_smaller(arr1: &Vec<i32>, arr2: &Vec<i32>) -> (res: bool)
    requires
        arr1.len() == arr2.len(),
    ensures
        res <==> vec_strictly_greater(arr1@.map_values(|x: i32| x as int),
                                      arr2@.map_values(|x: i32| x as int)),
{
    // Assumes arr1.len() == arr2.len()
    for i in 0..arr1.len()
        invariant
            arr1.len() == arr2.len(),
            0 <= i <= arr1.len(),
            // If we have not returned yet, all earlier indices satisfied arr1[j] > arr2[j]
            forall|j: int| 0 <= j < i ==> arr1@[j] as int > arr2@[j] as int,
    {
        if arr1[i] <= arr2[i] {
            return false;
        }
        // After the check, we learn arr1[i] > arr2[i] and extend the invariant.
        assert(arr1@[i as int] as int > arr2@[i as int] as int);
    }
    true
}

} // verus!

